const msg = ($json.text || '').toLowerCase();
let reply = '';

if (msg.includes('مرحبا') || msg.includes('السلام')) {
  reply = 'وعليكم السلام ورحمة الله وبركاته! 👋 أنا مساعد n8n. هل ترغب أن أشرح لك طريقة تحويل النص إلى صوت مجانًا؟';
} else if (msg.includes('نعم') || msg.includes('ايوا')) {
  reply = 'يمكنك استخدام موقع مثل Google Translate أو TTSMP3 لتحويل النصوص العربية إلى صوت طبيعي مجانًا. فقط انسخ النص وألصقه هناك واضغط "تحويل".';
} else {
  reply = 'أهلًا بك! أرسل لي كلمة "مرحبا" أو "السلام عليكم" لبدء المحادثة بالعربية.';
}

return [{ json: { reply } }];
